/**
 * Who took each photograph, under what licence, and where the original lives.
 *
 * This is not a courtesy list. Most place photography here comes from
 * Wikimedia Commons under CC BY / CC BY-SA, where naming the author and the
 * licence is a condition of being allowed to use the image at all — so a photo
 * with no entry here must not be displayed.
 *
 * The Commons block below is generated by scripts/generate-photo-data.mjs from
 * the last fetch run — edits there are lost on the next run. Photos from any
 * other source go in MANUAL_CREDITS, which the generator never touches.
 */
export interface PhotoCredit {
  /** Photographer or uploader, as the source records them. */
  artist: string;
  /** Short licence name, e.g. "CC BY-SA 3.0". */
  licence: string;
  /** The image's own page at the source — where the full licence text lives. */
  sourceUrl: string;
  /**
   * The Wikidata entity the photo was attached to, which is what proves it
   * depicts this place. Absent for the few photos that did not come through
   * that pipeline; those carry their evidence in a comment instead.
   */
  entity?: string;
}

/**
 * Photos not sourced from Commons, kept by hand.
 *
 * Each one needs a reason it can be trusted to show the place it is captioned
 * with, written down here, because nothing automatic checked it.
 */
const MANUAL_CREDITS: Record<string, PhotoCredit> = {
  // Wat Umong has no Wikidata entity within 400m, so the fetcher cannot reach
  // it. This is the one survivor of the old Pexels set: its source title is
  // "man posing in historic thai temple tunnel", and the image shows the brick
  // tunnel with a gilded Buddha at the end, which no other temple in Chiang Mai
  // has. Pexels does not require attribution; the photographer is named anyway.
  "wat-umong": {
    artist: "Pete Miller Portraits",
    licence: "Pexels licence",
    sourceUrl: "https://www.pexels.com/photo/man-posing-in-historic-thai-temple-tunnel-35446052/",
  },
};

