/** Generated Commons credits plus the hand-kept ones, as one lookup. */
const allCredits: Record<string, PhotoCredit> = { ...photoCredits, ...MANUAL_CREDITS };

export function getPhotoCredit(slug: string): PhotoCredit | undefined {
  return allCredits[slug];
}

/** Every credited photo, for the credits page. */
export function allPhotoCredits(): (PhotoCredit & { slug: string })[] {
  return Object.entries(allCredits)
    .map(([slug, credit]) => ({ slug, ...credit }))
    .sort((a, b) => a.slug.localeCompare(b.slug));
}

export default allCredits;
